@Test
public void testClassify() {
    // arrange
    TestLine line = TestLine.X_AXIS;
    StubRegion1D region = new StubRegion1D();
    // act/assert
    Assert.assertEquals(RegionLocation.INSIDE, HyperplaneSubsets.classifyAgainstEmbeddedRegion(new TestPoint2D(-1, 0), line, region));
    Assert.assertEquals(RegionLocation.BOUNDARY, HyperplaneSubsets.classifyAgainstEmbeddedRegion(new TestPoint2D(0, 0), line, region));
    Assert.assertEquals(RegionLocation.OUTSIDE, HyperplaneSubsets.classifyAgainstEmbeddedRegion(new TestPoint2D(0, 1), line, region));
    Assert.assertEquals(RegionLocation.OUTSIDE, HyperplaneSubsets.classifyAgainstEmbeddedRegion(new TestPoint2D(-1, 1), line, region));
    Assert.assertEquals(RegionLocation.OUTSIDE, HyperplaneSubsets.classifyAgainstEmbeddedRegion(new TestPoint2D(-1, -1), line, region));
}

@Test
public void testClosest() {
    // arrange
    TestLine line = TestLine.X_AXIS;
    StubRegion1D region = new StubRegion1D();
    StubRegion1D emptyRegion = new StubRegion1D(true);
    // act/assert
    PartitionTestUtils.assertPointsEqual(new TestPoint2D(-1, 0), HyperplaneSubsets.closestToEmbeddedRegion(new TestPoint2D(-1, 0), line, region));
    PartitionTestUtils.assertPointsEqual(new TestPoint2D(0, 0), HyperplaneSubsets.closestToEmbeddedRegion(new TestPoint2D(0, 0), line, region));
    PartitionTestUtils.assertPointsEqual(new TestPoint2D(0, 0), HyperplaneSubsets.closestToEmbeddedRegion(new TestPoint2D(1, 0), line, region));
    PartitionTestUtils.assertPointsEqual(new TestPoint2D(0, 0), HyperplaneSubsets.closestToEmbeddedRegion(new TestPoint2D(1, 1), line, region));
    PartitionTestUtils.assertPointsEqual(new TestPoint2D(0, 0), HyperplaneSubsets.closestToEmbeddedRegion(new TestPoint2D(1, -1), line, region));
    PartitionTestUtils.assertPointsEqual(new TestPoint2D(-1, 0), HyperplaneSubsets.closestToEmbeddedRegion(new TestPoint2D(-1, 1), line, region));
    PartitionTestUtils.assertPointsEqual(new TestPoint2D(-1, 0), HyperplaneSubsets.closestToEmbeddedRegion(new TestPoint2D(-1, -1), line, region));
    Assert.assertNull(HyperplaneSubsets.closestToEmbeddedRegion(TestPoint2D.ZERO, line, emptyRegion));
}

