    tree.getRoot().cut(TestLine.Y_AXIS).getPlus().cut(new TestLine(new TestPoint2D(0, 0), new TestPoint2D(1, 1))).getPlus().cut(new TestLine(new TestPoint2D(1.5, 1.5), new TestPoint2D(2, 1)));
    TestNode root = tree.getRoot();
    TestNode plus = root.getPlus();
    TestNode plusMinus = plus.getMinus();
    TestNode plusPlusPlus = plus.getPlus().getPlus();
    TestLineSegment xAxisSeg = TestLine.X_AXIS.span();
    TestLineSegment shortSeg = new TestLineSegment(new TestPoint2D(2, 0), new TestPoint2D(2, 2));
    // act/assert
    Assert.assertSame(xAxisSeg, root.trim(xAxisSeg));
    Assert.assertSame(shortSeg, root.trim(shortSeg));
    PartitionTestUtils.assertSegmentsEqual(new TestLineSegment(0, Double.POSITIVE_INFINITY, TestLine.X_AXIS), (TestLineSegment) plus.trim(xAxisSeg));
    Assert.assertSame(shortSeg, plus.trim(shortSeg));
    Assert.assertNull(plusMinus.trim(xAxisSeg));
    Assert.assertNull(plusMinus.trim(shortSeg));
    PartitionTestUtils.assertSegmentsEqual(new TestLineSegment(0, 3, TestLine.X_AXIS), (TestLineSegment) plusPlusPlus.trim(xAxisSeg));
    PartitionTestUtils.assertSegmentsEqual(new TestLineSegment(new TestPoint2D(2, 0), new TestPoint2D(2, 1)), (TestLineSegment) plusPlusPlus.trim(shortSeg));
}

