@Test
public void testIntersection() {
    // -- arrange
    Bounds3D b = Bounds3D.from(Vector3D.ZERO, Vector3D.of(1, 1, 1));
    // -- act/assert
    // move along x-axis
    Assert.assertNull(b.intersection(Bounds3D.from(Vector3D.of(-2, 0, 0), Vector3D.of(-1, 1, 1))));
    checkIntersection(b, Vector3D.of(-1, 0, 0), Vector3D.of(0, 1, 1), Vector3D.of(0, 0, 0), Vector3D.of(0, 1, 1));
    checkIntersection(b, Vector3D.of(-1, 0, 0), Vector3D.of(0.5, 1, 1), Vector3D.of(0, 0, 0), Vector3D.of(0.5, 1, 1));
    checkIntersection(b, Vector3D.of(-1, 0, 0), Vector3D.of(1, 1, 1), Vector3D.of(0, 0, 0), Vector3D.of(1, 1, 1));
    checkIntersection(b, Vector3D.of(-1, 0, 0), Vector3D.of(2, 1, 1), Vector3D.of(0, 0, 0), Vector3D.of(1, 1, 1));
    checkIntersection(b, Vector3D.of(0, 0, 0), Vector3D.of(2, 1, 1), Vector3D.of(0, 0, 0), Vector3D.of(1, 1, 1));
    checkIntersection(b, Vector3D.of(0.5, 0, 0), Vector3D.of(2, 1, 1), Vector3D.of(0.5, 0, 0), Vector3D.of(1, 1, 1));
    checkIntersection(b, Vector3D.of(1, 0, 0), Vector3D.of(2, 1, 1), Vector3D.of(1, 0, 0), Vector3D.of(1, 1, 1));
    Assert.assertNull(b.intersection(Bounds3D.from(Vector3D.of(2, 0, 0), Vector3D.of(3, 1, 1))));
    // move along y-axis
    Assert.assertNull(b.intersection(Bounds3D.from(Vector3D.of(0, -2, 0), Vector3D.of(1, -1, 1))));
    checkIntersection(b, Vector3D.of(0, -1, 0), Vector3D.of(1, 0, 1), Vector3D.of(0, 0, 0), Vector3D.of(1, 0, 1));
    checkIntersection(b, Vector3D.of(0, -1, 0), Vector3D.of(1, 0.5, 1), Vector3D.of(0, 0, 0), Vector3D.of(1, 0.5, 1));
    checkIntersection(b, Vector3D.of(0, -1, 0), Vector3D.of(1, 1, 1), Vector3D.of(0, 0, 0), Vector3D.of(1, 1, 1));
    checkIntersection(b, Vector3D.of(0, -1, 0), Vector3D.of(1, 2, 1), Vector3D.of(0, 0, 0), Vector3D.of(1, 1, 1));
    checkIntersection(b, Vector3D.of(0, 0, 0), Vector3D.of(1, 2, 1), Vector3D.of(0, 0, 0), Vector3D.of(1, 1, 1));
    checkIntersection(b, Vector3D.of(0, 0.5, 0), Vector3D.of(1, 2, 1), Vector3D.of(0, 0.5, 0), Vector3D.of(1, 1, 1));
    checkIntersection(b, Vector3D.of(0, 1, 0), Vector3D.of(1, 2, 1), Vector3D.of(0, 1, 0), Vector3D.of(1, 1, 1));
    Assert.assertNull(b.intersection(Bounds3D.from(Vector3D.of(0, 2, 0), Vector3D.of(1, 3, 1))));
    // move along z-axis
    Assert.assertNull(b.intersection(Bounds3D.from(Vector3D.of(0, 0, -2), Vector3D.of(1, 1, -1))));
    checkIntersection(b, Vector3D.of(0, 0, -1), Vector3D.of(1, 1, 0), Vector3D.of(0, 0, 0), Vector3D.of(1, 1, 0));
    checkIntersection(b, Vector3D.of(0, 0, -1), Vector3D.of(1, 1, 0.5), Vector3D.of(0, 0, 0), Vector3D.of(1, 1, 0.5));
    checkIntersection(b, Vector3D.of(0, 0, -1), Vector3D.of(1, 1, 1), Vector3D.of(0, 0, 0), Vector3D.of(1, 1, 1));
    checkIntersection(b, Vector3D.of(0, 0, -1), Vector3D.of(1, 1, 2), Vector3D.of(0, 0, 0), Vector3D.of(1, 1, 1));
    checkIntersection(b, Vector3D.of(0, 0, 0), Vector3D.of(1, 1, 2), Vector3D.of(0, 0, 0), Vector3D.of(1, 1, 1));
    checkIntersection(b, Vector3D.of(0, 0, 0.5), Vector3D.of(1, 1, 2), Vector3D.of(0, 0, 0.5), Vector3D.of(1, 1, 1));
    checkIntersection(b, Vector3D.of(0, 0, 1), Vector3D.of(1, 1, 2), Vector3D.of(0, 0, 1), Vector3D.of(1, 1, 1));
    Assert.assertNull(b.intersection(Bounds3D.from(Vector3D.of(0, 0, 2), Vector3D.of(1, 1, 3))));
}

