        AffineTransformMatrix3D transform = AffineTransformMatrix3D.createTranslation(Vector3D.of(a, b, c)).rotate(QuaternionRotation.fromAxisAngle(Vector3D.of(b, c, a), PlaneAngleRadians.PI * c)).scale(0.1, 4, 8);
        // act
        SubspaceTransform st = plane.subspaceTransform(transform);
        // assert
        EuclideanTestUtils.permute(-5, 5, 1, (x, y) -> {
            Vector2D subPt = Vector2D.of(x, y);
            Vector3D expected = transform.apply(plane.toSpace(subPt));
            Vector3D actual = st.getPlane().toSpace(st.getTransform().apply(subPt));
            EuclideanTestUtils.assertCoordinatesEqual(expected, actual, TEST_EPS);
        });
    });
}

