@Test
public void testGeometricProperties_mixedCutRules() {
    // act
    RegionBSPTree3D tree = RegionBSPTree3D.empty();
    Vector3D min = Vector3D.ZERO;
    Vector3D max = Vector3D.of(1, 1, 1);
    Plane top = Planes.fromPointAndNormal(max, Vector3D.Unit.PLUS_Z, TEST_PRECISION);
    Plane bottom = Planes.fromPointAndNormal(min, Vector3D.Unit.MINUS_Z, TEST_PRECISION);
    Plane left = Planes.fromPointAndNormal(min, Vector3D.Unit.MINUS_X, TEST_PRECISION);
    Plane right = Planes.fromPointAndNormal(max, Vector3D.Unit.PLUS_X, TEST_PRECISION);
    Plane front = Planes.fromPointAndNormal(min, Vector3D.Unit.MINUS_Y, TEST_PRECISION);
    Plane back = Planes.fromPointAndNormal(max, Vector3D.Unit.PLUS_Y, TEST_PRECISION);
    Plane diag = Planes.fromPointAndNormal(Vector3D.of(0.5, 0.5, 0.5), Vector3D.of(0.5, -0.5, 0), TEST_PRECISION);
    Plane midCut = Planes.fromPointAndNormal(Vector3D.of(0.5, 0.5, 0.5), Vector3D.Unit.PLUS_Z, TEST_PRECISION);
    tree.getRoot().cut(diag, RegionCutRule.INHERIT);
    tree.getRoot().getMinus().cut(top).getMinus().cut(bottom.reverse(), RegionCutRule.PLUS_INSIDE).getPlus().cut(left, RegionCutRule.MINUS_INSIDE).getMinus().cut(back.reverse(), RegionCutRule.PLUS_INSIDE).getPlus().cut(midCut, RegionCutRule.INHERIT);
    tree.getRoot().getPlus().cut(top.reverse(), RegionCutRule.PLUS_INSIDE).getPlus().cut(bottom).getMinus().cut(right, RegionCutRule.MINUS_INSIDE).getMinus().cut(front.reverse(), RegionCutRule.PLUS_INSIDE).getPlus().cut(midCut, RegionCutRule.INHERIT);
    // assert
    Assert.assertFalse(tree.isEmpty());
    Assert.assertFalse(tree.isFull());
    Assert.assertEquals(1, tree.getSize(), TEST_EPS);
    Assert.assertEquals(6, tree.getBoundarySize(), TEST_EPS);
    EuclideanTestUtils.assertCoordinatesEqual(Vector3D.of(0.5, 0.5, 0.5), tree.getCentroid(), TEST_EPS);
    EuclideanTestUtils.assertRegionLocation(tree, RegionLocation.INSIDE, Vector3D.of(0.5, 0.5, 0.5));
    EuclideanTestUtils.assertRegionLocation(tree, RegionLocation.BOUNDARY, min, max);
    EuclideanTestUtils.assertRegionLocation(tree, RegionLocation.OUTSIDE, Vector3D.of(2, 2, 2), Vector3D.of(2, 2, -2), Vector3D.of(2, -2, 2), Vector3D.of(2, -2, -2), Vector3D.of(-2, 2, 2), Vector3D.of(-2, 2, -2), Vector3D.of(-2, -2, 2), Vector3D.of(-2, -2, -2));
}

