@Test
public void testLinecast_complexRegion() {
    // arrange
    RegionBSPTree3D a = RegionBSPTree3D.empty();
    Parallelepiped.axisAligned(Vector3D.ZERO, Vector3D.of(0.5, 1, 1), TEST_PRECISION).boundaryStream().map(PlaneConvexSubset::reverse).forEach(a::insert);
    a.complement();
    RegionBSPTree3D b = RegionBSPTree3D.empty();
    Parallelepiped.axisAligned(Vector3D.of(0.5, 0, 0), Vector3D.of(1, 1, 1), TEST_PRECISION).boundaryStream().map(PlaneConvexSubset::reverse).forEach(b::insert);
    b.complement();
    RegionBSPTree3D c = createRect(Vector3D.of(0.5, 0.5, 0.5), Vector3D.of(1.5, 1.5, 1.5));
    RegionBSPTree3D tree = RegionBSPTree3D.empty();
    tree.union(a, b);
    tree.union(c);
    // act/assert
    Vector3D corner = Vector3D.of(1.5, 1.5, 1.5);
    LinecastChecker3D.with(tree).expect(corner, Vector3D.Unit.PLUS_Z).and(corner, Vector3D.Unit.PLUS_Y).and(corner, Vector3D.Unit.PLUS_X).whenGiven(Lines3D.segmentFromPoints(Vector3D.of(0.25, 0.25, 0.25), Vector3D.of(2, 2, 2), TEST_PRECISION));
}

