@Test
public void testLinecastFirst_multipleDirections() {
    // arrange
    RegionBSPTree3D tree = createRect(Vector3D.of(-1, -1, -1), Vector3D.of(1, 1, 1));
    Line3D xPlus = Lines3D.fromPoints(Vector3D.ZERO, Vector3D.of(1, 0, 0), TEST_PRECISION);
    Line3D xMinus = Lines3D.fromPoints(Vector3D.ZERO, Vector3D.of(-1, 0, 0), TEST_PRECISION);
    Line3D yPlus = Lines3D.fromPoints(Vector3D.ZERO, Vector3D.of(0, 1, 0), TEST_PRECISION);
    Line3D yMinus = Lines3D.fromPoints(Vector3D.ZERO, Vector3D.of(0, -1, 0), TEST_PRECISION);
    Line3D zPlus = Lines3D.fromPoints(Vector3D.ZERO, Vector3D.of(0, 0, 1), TEST_PRECISION);
    Line3D zMinus = Lines3D.fromPoints(Vector3D.ZERO, Vector3D.of(0, 0, -1), TEST_PRECISION);
    // act/assert
    EuclideanTestUtils.assertCoordinatesEqual(Vector3D.of(-1, 0, 0), tree.linecastFirst(xPlus.rayFrom(Vector3D.of(-1.1, 0, 0))).getNormal(), TEST_EPS);
    EuclideanTestUtils.assertCoordinatesEqual(Vector3D.of(-1, 0, 0), tree.linecastFirst(xPlus.rayFrom(Vector3D.of(-1, 0, 0))).getNormal(), TEST_EPS);
    EuclideanTestUtils.assertCoordinatesEqual(Vector3D.of(1, 0, 0), tree.linecastFirst(xPlus.rayFrom(Vector3D.of(-0.9, 0, 0))).getNormal(), TEST_EPS);
    Assert.assertNull(tree.linecastFirst(xPlus.rayFrom(Vector3D.of(1.1, 0, 0))));
    EuclideanTestUtils.assertCoordinatesEqual(Vector3D.of(1, 0, 0), tree.linecastFirst(xMinus.rayFrom(Vector3D.of(1.1, 0, 0))).getNormal(), TEST_EPS);
    EuclideanTestUtils.assertCoordinatesEqual(Vector3D.of(1, 0, 0), tree.linecastFirst(xMinus.rayFrom(Vector3D.of(1, 0, 0))).getNormal(), TEST_EPS);
    EuclideanTestUtils.assertCoordinatesEqual(Vector3D.of(-1, 0, 0), tree.linecastFirst(xMinus.rayFrom(Vector3D.of(0.9, 0, 0))).getNormal(), TEST_EPS);
    Assert.assertNull(tree.linecastFirst(xMinus.rayFrom(Vector3D.of(-1.1, 0, 0))));
    EuclideanTestUtils.assertCoordinatesEqual(Vector3D.of(0, -1, 0), tree.linecastFirst(yPlus.rayFrom(Vector3D.of(0, -1.1, 0))).getNormal(), TEST_EPS);
    EuclideanTestUtils.assertCoordinatesEqual(Vector3D.of(0, -1, 0), tree.linecastFirst(yPlus.rayFrom(Vector3D.of(0, -1, 0))).getNormal(), TEST_EPS);
    EuclideanTestUtils.assertCoordinatesEqual(Vector3D.of(0, 1, 0), tree.linecastFirst(yPlus.rayFrom(Vector3D.of(0, -0.9, 0))).getNormal(), TEST_EPS);
    Assert.assertNull(tree.linecastFirst(yPlus.rayFrom(Vector3D.of(0, 1.1, 0))));
    EuclideanTestUtils.assertCoordinatesEqual(Vector3D.of(0, 1, 0), tree.linecastFirst(yMinus.rayFrom(Vector3D.of(0, 1.1, 0))).getNormal(), TEST_EPS);
    EuclideanTestUtils.assertCoordinatesEqual(Vector3D.of(0, 1, 0), tree.linecastFirst(yMinus.rayFrom(Vector3D.of(0, 1, 0))).getNormal(), TEST_EPS);
    EuclideanTestUtils.assertCoordinatesEqual(Vector3D.of(0, -1, 0), tree.linecastFirst(yMinus.rayFrom(Vector3D.of(0, 0.9, 0))).getNormal(), TEST_EPS);
    Assert.assertNull(tree.linecastFirst(yMinus.rayFrom(Vector3D.of(0, -1.1, 0))));
    EuclideanTestUtils.assertCoordinatesEqual(Vector3D.of(0, 0, -1), tree.linecastFirst(zPlus.rayFrom(Vector3D.of(0, 0, -1.1))).getNormal(), TEST_EPS);
    EuclideanTestUtils.assertCoordinatesEqual(Vector3D.of(0, 0, -1), tree.linecastFirst(zPlus.rayFrom(Vector3D.of(0, 0, -1))).getNormal(), TEST_EPS);
    EuclideanTestUtils.assertCoordinatesEqual(Vector3D.of(0, 0, 1), tree.linecastFirst(zPlus.rayFrom(Vector3D.of(0, 0, -0.9))).getNormal(), TEST_EPS);
    Assert.assertNull(tree.linecastFirst(zPlus.rayFrom(Vector3D.of(0, 0, 1.1))));
    EuclideanTestUtils.assertCoordinatesEqual(Vector3D.of(0, 0, 1), tree.linecastFirst(zMinus.rayFrom(Vector3D.of(0, 0, 1.1))).getNormal(), TEST_EPS);
    EuclideanTestUtils.assertCoordinatesEqual(Vector3D.of(0, 0, 1), tree.linecastFirst(zMinus.rayFrom(Vector3D.of(0, 0, 1))).getNormal(), TEST_EPS);
    EuclideanTestUtils.assertCoordinatesEqual(Vector3D.of(0, 0, -1), tree.linecastFirst(zMinus.rayFrom(Vector3D.of(0, 0, 0.9))).getNormal(), TEST_EPS);
    Assert.assertNull(tree.linecastFirst(zMinus.rayFrom(Vector3D.of(0, 0, -1.1))));
}

