@Test
public void testFromTransformedUnitCube() {
    // arrange
    AffineTransformMatrix3D t = AffineTransformMatrix3D.createTranslation(Vector3D.of(1, 0, 2)).rotate(QuaternionRotation.fromAxisAngle(Vector3D.Unit.PLUS_Z, Math.PI * 0.25)).scale(Vector3D.of(2, 1, 1));
    // act
    Parallelepiped p = Parallelepiped.fromTransformedUnitCube(t, TEST_PRECISION);
    // assert
    double sqrt2 = Math.sqrt(2);
    double invSqrt2 = 1 / sqrt2;
    Assert.assertEquals(2, p.getSize(), TEST_EPS);
    Assert.assertEquals(4 + (4 * Math.sqrt(2.5)), p.getBoundarySize(), TEST_EPS);
    EuclideanTestUtils.assertCoordinatesEqual(Vector3D.of(2 * invSqrt2, invSqrt2, 2), p.getCentroid(), TEST_EPS);
    assertVertices(p, Vector3D.of(0, invSqrt2, 1.5), Vector3D.of(2 * invSqrt2, 0, 1.5), Vector3D.of(2 * sqrt2, invSqrt2, 1.5), Vector3D.of(2 * invSqrt2, sqrt2, 1.5), Vector3D.of(0, invSqrt2, 2.5), Vector3D.of(2 * invSqrt2, 0, 2.5), Vector3D.of(2 * sqrt2, invSqrt2, 2.5), Vector3D.of(2 * invSqrt2, sqrt2, 2.5));
}

