    AffineTransformMatrix3D t = AffineTransformMatrix3D.identity().rotate(QuaternionRotation.fromAxisAngle(Vector3D.Unit.PLUS_Y, -PlaneAngleRadians.PI_OVER_TWO)).scale(1, 1, 2).translate(Vector3D.of(1, 0, 0));
    VertexListConvexPolygon3D p = new VertexListConvexPolygon3D(XY_PLANE_Z1, Arrays.asList(Vector3D.of(1, 2, 1), Vector3D.of(3, 2, 1), Vector3D.of(3, 4, 1), Vector3D.of(1, 4, 1)));
    // act
    VertexListConvexPolygon3D result = p.transform(t);
    // assert
    Assert.assertFalse(result.isFull());
    Assert.assertFalse(result.isEmpty());
    Assert.assertTrue(result.isFinite());
    Assert.assertFalse(result.isInfinite());
    Assert.assertEquals(8, result.getSize(), TEST_EPS);
    EuclideanTestUtils.assertCoordinatesEqual(Vector3D.Unit.MINUS_X, result.getPlane().getNormal(), TEST_EPS);
    EuclideanTestUtils.assertVertexLoopSequence(Arrays.asList(Vector3D.of(0, 2, 2), Vector3D.of(0, 2, 6), Vector3D.of(0, 4, 6), Vector3D.of(0, 4, 2)), result.getVertices(), TEST_PRECISION);
}

