@Test
public void testIntersection() {
    // -- arrange
    Bounds2D b = Bounds2D.from(Vector2D.ZERO, Vector2D.of(1, 1));
    // -- act/assert
    // move along x-axis
    Assert.assertNull(b.intersection(Bounds2D.from(Vector2D.of(-2, 0), Vector2D.of(-1, 1))));
    checkIntersection(b, Vector2D.of(-1, 0), Vector2D.of(0, 1), Vector2D.of(0, 0), Vector2D.of(0, 1));
    checkIntersection(b, Vector2D.of(-1, 0), Vector2D.of(0.5, 1), Vector2D.of(0, 0), Vector2D.of(0.5, 1));
    checkIntersection(b, Vector2D.of(-1, 0), Vector2D.of(1, 1), Vector2D.of(0, 0), Vector2D.of(1, 1));
    checkIntersection(b, Vector2D.of(-1, 0), Vector2D.of(2, 1), Vector2D.of(0, 0), Vector2D.of(1, 1));
    checkIntersection(b, Vector2D.of(0, 0), Vector2D.of(2, 1), Vector2D.of(0, 0), Vector2D.of(1, 1));
    checkIntersection(b, Vector2D.of(0.5, 0), Vector2D.of(2, 1), Vector2D.of(0.5, 0), Vector2D.of(1, 1));
    checkIntersection(b, Vector2D.of(1, 0), Vector2D.of(2, 1), Vector2D.of(1, 0), Vector2D.of(1, 1));
    Assert.assertNull(b.intersection(Bounds2D.from(Vector2D.of(2, 0), Vector2D.of(3, 1))));
    // move along y-axis
    Assert.assertNull(b.intersection(Bounds2D.from(Vector2D.of(0, -2), Vector2D.of(1, -1))));
    checkIntersection(b, Vector2D.of(0, -1), Vector2D.of(1, 0), Vector2D.of(0, 0), Vector2D.of(1, 0));
    checkIntersection(b, Vector2D.of(0, -1), Vector2D.of(1, 0.5), Vector2D.of(0, 0), Vector2D.of(1, 0.5));
    checkIntersection(b, Vector2D.of(0, -1), Vector2D.of(1, 1), Vector2D.of(0, 0), Vector2D.of(1, 1));
    checkIntersection(b, Vector2D.of(0, -1), Vector2D.of(1, 2), Vector2D.of(0, 0), Vector2D.of(1, 1));
    checkIntersection(b, Vector2D.of(0, 0), Vector2D.of(1, 2), Vector2D.of(0, 0), Vector2D.of(1, 1));
    checkIntersection(b, Vector2D.of(0, 0.5), Vector2D.of(1, 2), Vector2D.of(0, 0.5), Vector2D.of(1, 1));
    checkIntersection(b, Vector2D.of(0, 1), Vector2D.of(1, 2), Vector2D.of(0, 1), Vector2D.of(1, 1));
    Assert.assertNull(b.intersection(Bounds2D.from(Vector2D.of(0, 2), Vector2D.of(1, 3))));
}

