@Test
public void testSplit() {
    // --- arrange
    Vector2D p0 = Vector2D.of(1, 1);
    Vector2D p1 = Vector2D.of(3, 1);
    Vector2D low = Vector2D.of(0, 1);
    Vector2D delta = Vector2D.of(1e-11, 1e-11);
    Ray ray = Lines.rayFromPointAndDirection(p0, Vector2D.Unit.PLUS_X, TEST_PRECISION);
    // --- act
    // parallel
    checkSplit(ray.split(Lines.fromPointAndAngle(Vector2D.of(2, 2), 0, TEST_PRECISION)), null, null, p0, null);
    checkSplit(ray.split(Lines.fromPointAndAngle(Vector2D.of(2, 2), Math.PI, TEST_PRECISION)), p0, null, null, null);
    // coincident
    checkSplit(ray.split(Lines.fromPointAndAngle(p0.add(delta), 1e-20, TEST_PRECISION)), null, null, null, null);
    // through point on ray
    checkSplit(ray.split(Lines.fromPointAndAngle(p1, 1, TEST_PRECISION)), p0, p1, p1, null);
    checkSplit(ray.split(Lines.fromPointAndAngle(p1, -1, TEST_PRECISION)), p1, null, p0, p1);
    // through start point
    checkSplit(ray.split(Lines.fromPointAndAngle(p0.subtract(delta), 1, TEST_PRECISION)), null, null, p0, null);
    checkSplit(ray.split(Lines.fromPointAndAngle(p0.add(delta), -1, TEST_PRECISION)), p0, null, null, null);
    // intersection below minus
    checkSplit(ray.split(Lines.fromPointAndAngle(low, 1, TEST_PRECISION)), null, null, p0, null);
    checkSplit(ray.split(Lines.fromPointAndAngle(low, -1, TEST_PRECISION)), p0, null, null, null);
}

