    Assert.assertTrue(a.eq(d, precision));
    Assert.assertTrue(a.eq(e, precision));
    Assert.assertTrue(a.eq(f, precision));
    Assert.assertTrue(a.eq(g, precision));
    Assert.assertTrue(a.eq(h, precision));
}

