    DoublePrecisionContext precision = new EpsilonDoublePrecisionContext(1e-3);
    GreatCircle a = GreatCircles.fromPoleAndU(Vector3D.Unit.PLUS_Z, Vector3D.Unit.PLUS_X, TEST_PRECISION);
