    Assert.assertTrue(a.eq(a, largeEps));
    Assert.assertTrue(a.eq(b, largeEps));
    Assert.assertTrue(a.eq(c, largeEps));
    Assert.assertTrue(a.eq(d, largeEps));
    Assert.assertFalse(a.eq(e, largeEps));
}

