@Test
public void testTransform() {
    // arrange
    Transform2S t = Transform2S.createReflection(Point2S.PLUS_J);
    RegionBSPTree2S tree = ConvexArea2S.fromVertexLoop(Arrays.asList(Point2S.PLUS_I, Point2S.PLUS_J, Point2S.PLUS_K), TEST_PRECISION).toTree();
    // act
    tree.transform(t);
    // assert
    Assert.assertFalse(tree.isFull());
    Assert.assertFalse(tree.isEmpty());
    Assert.assertEquals(1.5 * PlaneAngleRadians.PI, tree.getBoundarySize(), TEST_EPS);
    Assert.assertEquals(PlaneAngleRadians.PI_OVER_TWO, tree.getSize(), TEST_EPS);
    Point2S expectedCentroid = triangleCentroid(Point2S.MINUS_J, Point2S.PLUS_I, Point2S.PLUS_K);
    SphericalTestUtils.assertPointsEq(expectedCentroid, tree.getCentroid(), TEST_EPS);
    checkCentroidConsistency(tree);
    SphericalTestUtils.checkClassify(tree, RegionLocation.INSIDE, Point2S.of(-0.25 * PlaneAngleRadians.PI, 0.25 * PlaneAngleRadians.PI));
    SphericalTestUtils.checkClassify(tree, RegionLocation.BOUNDARY, Point2S.PLUS_I, Point2S.MINUS_J, Point2S.PLUS_K, Point2S.of(0, 0.25 * PlaneAngleRadians.PI), Point2S.of(-PlaneAngleRadians.PI_OVER_TWO, 0.304 * PlaneAngleRadians.PI), Point2S.of(-0.25 * PlaneAngleRadians.PI, PlaneAngleRadians.PI_OVER_TWO));
    SphericalTestUtils.checkClassify(tree, RegionLocation.OUTSIDE, Point2S.PLUS_J, Point2S.MINUS_I, Point2S.MINUS_K);
}

@Test
public void testRegionNode_getNodeRegion() {
